import requests
from eth_account import Account

INFURA_URL = "https://sepolia.infura.io/v3/4e23938591fe4329aefd1508441f6fc0"
PRIVATE_KEY = "cf1b369bee8f5c6f53c87a6327569ac62f24b01ca2eedfd9381d22fde202a307" 
BYTECODE = ""  # Le bytecode copié à l'étape 1

def call_ethereum_rpc(method, params=[]):
    payload = {
        "jsonrpc": "2.0",
        "method": method,
        "params": params,
        "id": 1
    }
    response = requests.post(INFURA_URL, json=payload, timeout=10)
    return response.json()

def deploy_contract():
    account = Account.from_key(PRIVATE_KEY)
    sender_address = account.address
    print(f"Adresse du déployeur : {sender_address}")

    # 1. Récupérer le nonce
    nonce_res = call_ethereum_rpc("eth_getTransactionCount", [sender_address, "latest"])
    nonce = int(nonce_res.get("result", "0x0"), 16)

    # 2. Récupérer le gas price
    gas_price_res = call_ethereum_rpc("eth_gasPrice", [])
    gas_price = int(gas_price_res.get("result", "0x3B9ACA00"), 16)

    # 3. Construire la transaction de déploiement (to = None / vide pour création de contrat)
    tx = {
        "nonce": nonce,
        "gasPrice": gas_price,
        "gas": 3000000,  # Limite de gas pour le déploiement
        "to": "",        # Vide pour un déploiement de contrat
        "value": 0,
        "data": BYTECODE,
        "chainId": 11155111 # ID du réseau Sepolia
    }

    # 4. Signer la transaction
    signed_tx = Account.sign_transaction(tx, PRIVATE_KEY)
    
    # 5. Envoyer la transaction brute
    print("Envoi de la transaction de déploiement sur Sepolia...")
    tx_res = call_ethereum_rpc(
    "eth_sendRawTransaction",
    ["0x" + signed_tx.raw_transaction.hex()],
)
    tx_hash = tx_res.get("result")
    
    if not tx_hash:
        print(f"Erreur lors du déploiement : {tx_res}")
        return
        
    print(f"Transaction envoyée ! Hash : {tx_hash}")
    print("Attente de la validation du bloc...")

    # 6. Attendre le reçu pour récupérer l'adresse du contrat déployé
    import time
    while True:
        receipt_res = call_ethereum_rpc("eth_getTransactionReceipt", [tx_hash])
        receipt = receipt_res.get("result")
        if receipt and receipt.get("contractAddress"):
            contract_address = receipt.get("contractAddress")
            print(f"\n Succès ! Votre contrat est déployé à l'adresse : {contract_address}")
            break
        time.sleep(3)

if __name__ == "__main__":
    deploy_contract()